#!/bin/bash
set -euo pipefail
IFS=$'\n\t'

readonly script_name="$(basename ${BASH_SOURCE[0]})"

if [[ $# -ne 1 ]] ; then
    echo "Usage: ./${script_name} <migration_name>"
    echo "...to create a new migration in grails-app/migrations/<migration_name>.groovy"
    exit 0
fi

readonly migration_name="${1}"

# date can do seconds on OSX - the trailing zeros pad to milliseconds, to match migrations generated by grails
readonly timestamp=`date +%s000`
# Deliberately fixed rather than `whoami`: the author is recorded in a committed
# changelog, and there is no reason to stamp a contributor's OS username into it.
readonly username="juralio"
readonly content="databaseChangeLog = {
    changeSet(author: \"${username} (generated)\", id: "${timestamp}-1") {
      /*
        insert your migration here, e.g.

        createTable(tableName: \"film\") {
            column(name: \"id\", type: \"int8\") {
                constraints(nullable: \"false\", primaryKey: \"true\", primaryKeyName: \"filmPK\")
            }
            column(name: \"title\", type: \"varchar(255)\")
            column(name: \"description\", type: \"text\")
        }
      */
    }
}"

readonly script_directory="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"
readonly migrations_directory="${script_directory}/grails-app/migrations"
readonly filename="${timestamp}_${migration_name}.groovy"
readonly filepath="${migrations_directory}/${filename}" 
readonly changelog_path="${migrations_directory}/changelog.groovy"
echo "Writing migration ${migration_name} to ${filepath}."
echo "${content}" > "${filepath}"

echo "Updating changelog to reference ${filename}."
sed -i '' "s/}/"$'\t'"include file: '${filename}'\\"$'\n'"}/" "${changelog_path}"

echo "Finished."
echo "Please update ${filepath} with your migration code."